function withHint(message: string, tag: unknown): string {
  if (tag === "Wallet.InsufficientFunds" && /dust/i.test(message)) {
    return `${message}. The wallet needs DUST to pay fees: hold NIGHT registered for DUST generation, then wait for DUST to accrue.`;
  }
  return message;
}

export circuit divide(num1: Uint<16>, num2: Uint<16>): [] {
    const [quo, rem] = divMod(num1, num2);
    assert(rem < num2 && quo * num2 + rem == num1, "incorrect division");
    // `quo` comes from the divMod witness; storing it in the public ledger is a
    // disclosure that must be declared explicitly. Writing state (rather than
    // just returning) makes this a proof-generating, on-chain circuit like the
    // other operations.
    result = disclose(quo);
}

export async function sponsorAndSubmit(
  logger: Logger,
  sponsor: MidnightWalletProvider,
  userTxHex: string,
): Promise<string> {
  // The marker triple matches `FinalizedTransaction = Transaction<SignatureEnabled, Proof, Binding>`.
  const userTx = Transaction.deserialize<SignatureEnabled, Proof, Binding>(
    'signature',
    'proof',
    'binding',
    fromHex(userTxHex),
  );

  logger.info('[sponsor] attaching DUST fee offer...');
  const sponsored = await sponsor.addDustFeesAndFinalize(userTx);

  const txId = await sponsor.wallet.submitTransaction(sponsored);
  logger.info(`[sponsor] submitted sponsored tx: ${txId}`);
  return txId;
}

export async function prepareSponsoredCall<
  C extends Contract.Any,
  PCK extends Contract.ProvableCircuitId<C>,
>(
  logger: Logger,
  user: MidnightWalletProvider,
  providers: PartyProviders,
  call: CallTxOptionsWithPrivateStateId<C, PCK>,
): Promise<string> {
  logger.info(`[user] building ${String(call.circuitId)}()...`);
  const unsubmitted = await createUnprovenCallTx<C, PCK>(providers, call);

  // Proving happens here, on the user's side — which is why the secret that
  // authenticates the caller never reaches the sponsor.
  logger.info(`[user] proving ${String(call.circuitId)}()...`);
  const unboundTx = await providers.proofProvider.proveTx(unsubmitted.private.unprovenTx);

  // Where a circuit moves user value — checkIn's entry fee — that value is paid
  // from the user's own balance, here.
  logger.info('[user] balancing own value side (no DUST) and binding...');
  const finalized = await user.balanceOwnValueAndFinalize(unboundTx);

  return toHex(finalized.serialize());
}

export circuit rsvp(_address: UserAddress, _secret: Bytes<32>): [] {
    const pubKey = getDappPublicKey(_secret);
    // caller authentication check
    assert(pubKey != organizer, "Organizer cannot RSVP to the party");

    // state verification check
    assert(partyState == PartyState.NOT_STARTED, "The party has already started");
    assert(hashedPartyGoers.size() < maxListSize, "The list is full");

    // party goer address remains private
    const commitHash = commitAddress(_secret, _address.bytes);
    assert(!hashedPartyGoers.member(commitHash), "You are already on the list");
    hashedPartyGoers.insert(commitHash);// doesn't need disclose bc persistentCommit

    if (hashedPartyGoers.size() == maxListSize) {
        // @TODO -- In the future, emit an event to the organizer here (MIP-0002)
        partyState = PartyState.READY;
    }
}

export circuit checkIn(address: UserAddress, _secret: Bytes<32>): [] {
    // state verification checks
    assert(partyState == PartyState.STARTED, "The party has not been started. Call the party police");
    assert(checkedInParty.size() < hashedPartyGoers.size(), "All guests have already checked in");

    const commitHash = commitAddress(_secret, address.bytes);

    // caller verification checks
    assert(hashedPartyGoers.member(commitHash), "You are not on the list");
    assert(!checkedInParty.member(disclose(address)), "You have already checked in");

    // take in unshielded payment, party goers are now public
    receiveUnshielded(nativeToken(), entryFee as Uint<128>);
    checkedInParty.insert(disclose(address));

    if(checkedInParty.size() == maxListSize) {
        partyState = PartyState.DOORS_CLOSED;
    }
}

